// ============================================================
// PANGI ORCHESTRATOR (TELEGRAM) — Message Extractor v2.0.0
// Produce el SOBRE CANÓNICO agnóstico al canal:
//   { channel, phone (identidad DB), remoteJid (transporte de
//     respuesta), pushName, messageText, messageType, ... }
// Mismos tipos canónicos que el extractor de WhatsApp:
//   text | image | document | audio | sticker | button_reply
// ============================================================

const update  = $input.first().json;
const message = update.message;

// Solo procesamos updates de tipo 'message'
if (!message) {
  return [{ json: { valid: false, reason: 'not_message_update', updateKeys: Object.keys(update) } }];
}

const chat = message.chat || {};
const from = message.from || {};

// ── FILTROS ───────────────────────────────────────────────
if (from.is_bot)              return [{ json: { valid: false, reason: 'from_bot' } }];
if (chat.type !== 'private')  return [{ json: { valid: false, reason: 'not_private_chat', chatType: chat.type } }];
if (!chat.id)                 return [{ json: { valid: false, reason: 'no_chat_id' } }];

const chatId = String(chat.id);

// ── IDENTIDAD ─────────────────────────────────────────────
// phone: identidad en DB con prefijo de canal → 'tg:123456789'
//        (users.phone es VARCHAR(30) genérico; 'web:<uuid>' en el futuro)
// remoteJid: id de transporte que el nodo de envío usa para responder
const phone     = 'tg:' + chatId;
const remoteJid = chatId;

const pushName = [from.first_name, from.last_name].filter(Boolean).join(' ').trim()
              || from.username || null;

// ── IDIOMA (bonus Telegram: language_code del cliente) ────
const rawLang = (from.language_code || '').toLowerCase();
const tgLanguage = rawLang.startsWith('es') ? 'es'
                 : rawLang.startsWith('en') ? 'en'
                 : rawLang.startsWith('pt') ? 'pt'
                 : null;

// ── CONTENIDO DEL MENSAJE → tipos canónicos ───────────────
let messageText = '';
let messageType = 'unknown';

if (message.text) {
  messageText = message.text;
  messageType = 'text';
} else if (message.photo) {
  messageText = message.caption || '[Imagen recibida]';
  messageType = 'image';
} else if (message.document) {
  messageText = `[Documento recibido: ${message.document.file_name || 'archivo'}]`;
  messageType = 'document';
} else if (message.voice || message.audio) {
  messageText = '[Audio recibido — función de voz próximamente]';
  messageType = 'audio';
} else if (message.sticker) {
  messageText = '[Sticker]';
  messageType = 'sticker';
} else if (message.location) {
  messageText = '[Ubicación recibida]';
  messageType = 'location';
}

if (!messageText) {
  return [{ json: { valid: false, reason: 'unsupported_or_empty_message', msgKeys: Object.keys(message) } }];
}
// ── DEDUP KEY ─────────────────────────────────────────────
// Álbum: las N fotos comparten media_group_id → solo una ejecución procesa.
// Mensaje normal: update_id (Telegram reusa el mismo id al reintentar webhooks).
const dedupKey = message.media_group_id
  ? `alb:${chatId}:${message.media_group_id}`
  : `upd:${chatId}:${update.update_id || message.message_id || Date.now()}`;
return [{ json: {
  valid: true,
  channel: 'telegram',
  phone,
  remoteJid,
  pushName,
  tgLanguage,
  messageText,
  messageType,
  messageId: String(message.message_id || ''),
  dedupKey,
  mediaGroupId: message.media_group_id || null,
  instance: 'telegram',
  timestamp: new Date((message.date || Math.floor(Date.now()/1000)) * 1000).toISOString()
}}];

// ============================================================
// ALLOWLIST DEMO v1.0 — restringe respuestas a IDs autorizados.
// VACÍA = modo abierto (todos pasan) para tus pruebas.
// Para el demo con el CEO de Pangi: agregar los 'tg:<chat_id>' del equipo
// (cada uno obtiene su id escribiendo a @userinfobot en Telegram).
// ============================================================

const ALLOWED_IDS = [
  // 'tg:123456789',   // Erick
  // 'tg:987654321',   // el CEO de Pangi
];

const m = $input.first().json;
if (!m.valid) return [{ json: m }];   // ya inválido: pasa al filtro estándar

if (ALLOWED_IDS.length > 0 && !ALLOWED_IDS.includes(m.phone)) {
  console.log(`[PANGI] Bloqueado por allowlist: ${m.phone}`);
  return [{ json: { valid: false, reason: 'not_in_allowlist', phone: m.phone } }];
}

return [{ json: m }];

// ============================================================
// PREPARAR ENVÍO TELEGRAM v2.0.0
// Recibe output de NOVA, SAGE, ATLAS o nodos de consentimiento.
// Sobre canónico → payload Telegram. Mantiene los mismos campos
// _underscore que la versión WhatsApp para el ciclo de sesión.
// ============================================================

const a = $json;

// Safeguard sessionId (idéntico a v1 WhatsApp)
const rawSessionId  = a.sessionId;
const safeSessionId = (rawSessionId !== null && rawSessionId !== undefined &&
                       Number.isInteger(Number(rawSessionId)) &&
                       Number(rawSessionId) > 0)
  ? Number(rawSessionId)
  : null;
if (!safeSessionId) {
  console.error(`[PANGI] ⚠️ sessionId inválido del agente: "${rawSessionId}". Agent: ${a.newActiveAgent}`);
}

// Safeguard chatId — sin esto Telegram devuelve 400
const chatId = a.remoteJid || null;
if (!chatId) {
  console.error(`[PANGI] ⚠️ remoteJid/chatId ausente en output del agente: ${a.newActiveAgent}`);
}

// Texto: fallback + límite duro de Telegram (4096 chars)
let text = a.responseText || 'Error interno. Por favor escribe de nuevo.';
if (text.length > 4000) text = text.slice(0, 4000) + '…';

return [{ json: {
  tgChatId: chatId,
  tgText:   text,
  _responseText:      a.responseText || '',
  _remoteJid:         chatId,
  _instance:          a.instance || 'telegram',
  _userId:            a.userId,
  _sessionId:         safeSessionId,
  _newActiveAgent:    a.newActiveAgent  || 'NOVA',
  _newSessionState:   a.newSessionState || 'active',
  _newSessionContext: a.newSessionContext || {}
}}];

// ============================================================
// FALLBACK TEXTO PLANO v1.0
// Markdown v1 de Telegram rechaza mensajes con entidades
// desbalanceadas (*, _, `). Si el envío falló, reintenta con
// el texto limpio de caracteres de formato.
// ============================================================
const prep  = $('📤 Preparar Envío Telegram').first().json;
const plain = (prep.tgText || '').replace(/[*_`\[\]]/g, '');
console.log(`[PANGI] Reintentando envío en texto plano para chat ${prep.tgChatId}`);
return [{ json: { tgChatId: prep.tgChatId, tgText: plain } }];

// Mensajes filtrados silenciosamente.
// Esto es intencional: no queremos responder a bots,
// grupos, estados, ni mensajes propios.
const reason = $json.reason || 'unknown';
console.log(`[PANGI] Mensaje ignorado. Razón: ${reason}`);
return [{ json: { ignored: true, reason } }];

const userId = $('🗄️ DB — Usuario').first().json.data[0].id;
return [{ json: {
  operation: 'getActiveSession',
  params: { userId }
}}];

// TRUE path: sesión activa encontrada en DB
const session  = $('🗄️ DB — Sesión Activa').first().json.data[0];
const userData = $('🗄️ DB — Usuario').first().json.data[0];
const msgData  = $('🔎 Extraer y Validar Mensaje').first().json;

// Extraer context como variable para reutilizar en userLanguage
const sessionContext = typeof session.context === 'string'
  ? JSON.parse(session.context || '{}')
  : (session.context || {});

return [{ json: {
  userId:         userData.id,
  userName:       userData.name || msgData.pushName || null,
  userLanguage:   sessionContext.language || userData.language || 'es',
  userPhone:      userData.phone,
  sessionId:      session.id,
  activeAgent:    session.active_agent,
  sessionState:   session.state,
  sessionContext,
  isNewSession:   false,
  messageText:    msgData.messageText,
  messageType:    msgData.messageType,
  remoteJid:      msgData.remoteJid,
  instance:       msgData.instance
}}];

// FALSE path: no hay sesión, la creamos con NOVA como agente inicial
const userId = $('🗄️ DB — Usuario').first().json.data[0].id;
return [{ json: {
  operation: 'createSession',
  params: { userId, agent: 'NOVA', state: 'initial', context: {} }
}}];

// FALSE path: sesión recién creada (o recuperada por ON CONFLICT)
const sessionResult = $('🗄️ DB — Crear Sesión').first().json;
const session       = sessionResult.data?.[0];
const userData      = $('🗄️ DB — Usuario').first().json.data?.[0];
const msgData       = $('🔎 Extraer y Validar Mensaje').first().json;

// Guard — si llegamos aquí sin sesión, hay un problema upstream no detectado
if (!userData) {
  throw new Error(
    `[PANGI] USER_NOT_FOUND — remoteJid: ${msgData?.remoteJid ?? 'desconocido'}`
  );
}
if (!session) {
  // Con Fix 1 (ON CONFLICT) esto no debería ocurrir nunca.
  // Si ocurre, significa que DB_MANAGER retornó success:false y llegó aquí igual.
  throw new Error(
    `[PANGI] SESSION_CREATE_FAILED — ` +
    `userId: ${userData.id} | ` +
    `error: ${sessionResult.error ?? 'unknown'} | ` +
    `detail: ${sessionResult._meta?.pgDetail ?? sessionResult.message ?? 'sin detalle'}`
  );
}

return [{ json: {
  userId:         userData.id,
  userName:       userData.name || msgData.pushName || null,
  userLanguage:   userData.language || 'es',
  userPhone:      userData.phone,
  sessionId:      session.id,
  activeAgent:    session.active_agent,
  sessionState:   session.state,
  sessionContext: typeof session.context === 'string'
                    ? JSON.parse(session.context || '{}')
                    : (session.context || {}),
  isNewSession:   true,
  messageText:    msgData.messageText,
  messageType:    msgData.messageType,
  remoteJid:      msgData.remoteJid,
  instance:       msgData.instance
}}];

// Este nodo recibe data de CUALQUIERA de los dos Normalizar nodes.
// $json contiene el contexto unificado de la sesión.
const s = $json;

// ── DEDUPLICACIÓN: evitar procesar el mismo mensaje dos veces en <5s ─────────
const now      = Date.now();
const msgText  = (s.messageText || '').trim();
const lastAt   = s.sessionContext?._last_msg_at   || 0;
const lastText = (s.sessionContext?._last_msg_text || '').trim();

if (msgText && msgText === lastText && (now - lastAt) < 5000) {
  return []; // Mensaje duplicado en ventana de 5s — detener flujo
}
// ─────────────────────────────────────────────────────────────────────────────

return [{ json: {
  operation: 'saveMessage',
  params: {
    userId:      s.userId,
    sessionId:   s.sessionId,
    agent:       s.activeAgent,
    role:        'user',
    message:     s.messageText,
    messageType: s.messageType
  },
  // Transportar contexto de sesión para nodos posteriores
  _session: {
    userId:         s.userId,
    userName:       s.userName,
    userLanguage:   s.userLanguage,
    userPhone:      s.userPhone,
    sessionId:      s.sessionId,
    activeAgent:    s.activeAgent,
    sessionState:   s.sessionState,
    sessionContext: {
      ...s.sessionContext,
      _last_msg_at:   now,
      _last_msg_text: msgText,
      _pending_intent: s.sessionContext?._pending_intent || null
    },
    isNewSession:   s.isNewSession,
    messageText:    s.messageText,
    messageType:    s.messageType,
    remoteJid:      s.remoteJid,
    instance:       s.instance
  }
}}];

// ============================================================
// INTENT ROUTER v2.3.0 — Multilingüe (ES + EN + PT)
// Fix v2.3.0:
//   - ctx declarado antes de sessionLang (ReferenceError fix)
//   - Consent requiere hasExplicitYes (no acepta "Hello" como consent)
//   - sessionLang ignorado durante awaiting_consent (lang por mensaje)
//   - detectLanguage ampliado: 'hi', 'hey', 'yes', 'sim', etc.
// ============================================================

const session = $('📦 Payload — Guardar Mensaje Entrante').first().json._session;

const txt         = (session.messageText || '').toLowerCase().trim();
const normalize   = (s) => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
const txtN        = normalize(session.messageText || '');
const msgType     = session.messageType;
const activeAgent = session.activeAgent;
const isNew       = session.isNewSession;

// ── DETECCIÓN DE IDIOMA ──────────────────────────────────────
const detectLanguage = (text) => {
  const t = ' ' + text + ' ';
  const PT = [
    'não ','você','obrigad','olá','boa tarde','boa noite','bom dia',' oi ',' sim ',
    'posso','também','então','cotação','preço','quanto custa','cirurgia',
    'procedimento','viagem','hospedagem','dentista','dente','clareamento',
    'lipoaspiração','mamoplastia','alinhador'
  ];
  const EN = [
    ' the ',' is ',' are ',' my ',
    ' want',' need',' have',' has ',
    "i'm ","i'd ","don't","can't","won't","i'll","i've ","i was ","i am ",
    ' what ',' how ',' where ',' does ',
    'hello','good morning','good afternoon','good evening','good night',
    ' hi ', ' hey ',
    'quote','price','surgery','dental work','tooth','teeth',
    'rhinoplasty','liposuction','tummy tuck','breast implant','breast augmentation',
    'breast reduction','blepharoplasty','facelift','face lift','ear surgery',
    'appointment','schedule','book ','booking','see a doctor','accommodation','lodging'
  ];
  const ES = ['hola', ' gracias', 'buenos ', 'buenas', ' qué ', 'cotizar', 'cotización', 'agendar', 'por favor', 'español'];
  if (PT.some(m => t.includes(m))) return 'pt';
  if (EN.some(m => t.includes(m))) return 'en';
  if (ES.some(m => t.includes(m))) return 'es';
  return null;
};

// ── ctx debe declararse ANTES de sessionLang ─────────────────
const ctx = session.sessionContext || {};

// ── FIX v2.3.0: durante consent, re-detectar idioma por mensaje
// Fuera del consent, respetar idioma guardado en sesión.
const sessionLang      = ctx.awaiting_consent ? null : (session.sessionContext?.language || null);
const freshDetect      = detectLanguage(txt);
const detectedLanguage = sessionLang
  ? sessionLang
  : (freshDetect || session.userLanguage || 'es');
const out = (extra) => ({ json: { ...session, detectedLanguage, ...extra } });

// Si el turno anterior guardó un pendingHandoff (ej: intención detectada en primer mensaje)
// lo procesamos aquí antes que cualquier otra lógica
const ctxPendingHandoff = ctx.pendingHandoff || null;
const ctxPendingMessage = ctx.pendingMessage || null;
if (ctxPendingHandoff && ctx.consent_given) {
  return [out({
    targetAgent:     'NOVA',
    intentDetected:  ctxPendingHandoff === 'SAGE' ? 'cotizar_keyword' : ctxPendingHandoff === 'ATLAS' ? 'comparar_keyword' : 'agendar_keyword',
    pendingHandoff:  ctxPendingHandoff,
    pendingMessage:  ctxPendingMessage
  })];
}

// ── CONSENT CHECK ─────────────────────────────────────────────
if (!ctx.consent_given) {
  if (ctx.awaiting_consent) {
    // v2.4: normalizar tildes ANTES del regex — \b de JS no funciona con acentos
    // v2.4.1: el NO se evalúa PRIMERO — una negación que contiene palabra
    // afirmativa ("no acepto", "I don't accept") es rechazo, no aceptación.
    const txtNC = txt.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const hasExplicitNo =
      /\b(no+|nao)[\s,.!¡¿?]*$/.test(txtNC) ||
      /\b(no|nunca|jamas|nao|not|don['’]?t|do not|doesn['’]?t)\b[\s\w'’]*\b(acepto|aceptar|quiero|deseo|autorizo|accept|agree|aceito|concordo|continuar|continue)\b/.test(txtNC) ||
      /\b(rechazo|rechazar|refuse|reject|decline|deny|recuso|cancelar|cancel)\b/.test(txtNC);
    const hasExplicitYes = !hasExplicitNo &&
      /\b(si|yes|sim|ok|dale|claro|acepto|aceptar|continuar|continue|adelante|de acuerdo|confirmo|por supuesto|sure|aceito|concordo|accept|agree|esta bien)\b/.test(txtNC);

    if (hasExplicitNo) {
      return [out({ targetAgent: 'CONSENT_REFUSED', intentDetected: 'consent_refused', pendingHandoff: null })];
    }
    if (hasExplicitYes) {
      return [out({ targetAgent: 'CONSENT_ACCEPTED', intentDetected: 'consent_accepted', pendingHandoff: null })];
    }
    // Respuesta ambigua (ej: "Hello", "ho", "?") → re-mostrar aviso en idioma detectado
    return [out({ targetAgent: 'CONSENT', intentDetected: 'needs_consent_reask', pendingHandoff: null })];
  }
  return [out({ targetAgent: 'CONSENT', intentDetected: 'needs_consent', pendingHandoff: null })];
}

// ── SAFETY: SAGE en Q&A activo → siempre continuar ───────────
const sageQAStates = ['gathering_profile','procedure_confirmed','questioning','summary','waiting_for_confirmation'];
const sageCtxState = session.sessionContext?.sage?.state || '';
if (activeAgent === 'SAGE' && sageQAStates.includes(sageCtxState) && !isNew) {
  return [out({ targetAgent: 'SAGE', intentDetected: 'sage_qa_active', pendingHandoff: null })];
}

// ── KW_SALUDO — definido ANTES de REGLA 1 ────────────────────
const KW_SALUDO = [
  'hola','buenos días','buenas tardes','buenas noches','buenas','inicio','empezar','comenzar','iniciar',
  'hello','hi ','hey ','good morning','good afternoon','good evening','good night','start','begin',
  'olá ','oi ','bom dia','boa tarde','boa noite','começar','ajuda','informação','informacao'
];
const hasSaludo = KW_SALUDO.some(kw => txtN.includes(normalize(kw)));
// ── SAFETY: NOVA en flujo de agendamiento activo → continuar ──
// Un flujo a medias no se abandona por keywords; solo "hola" (reset) escapa.
const novaSchedState = session.sessionContext?.nova?.state || '';
if (activeAgent === 'NOVA' && novaSchedState.startsWith('sched_') && !hasSaludo) {
  return [out({ targetAgent: 'NOVA', intentDetected: 'sched_active', pendingHandoff: null })];
}

// ── REGLA 1: Respetar agente activo — EXCEPTO saludos ────────
const hasExplicitAtlas = /^(atlas|comparar?|compare|destinos?|destinations?|quiero comparar|i want to compare|want to compare|quero comparar|ver destinos)$/i.test(txt);
const hasExplicitSage  = /^(sage|cotizar|cotar|nueva solicitud|new request|nova cotacao)$/i.test(txt);
if (activeAgent === 'SAGE'  && !isNew && !hasSaludo && !hasExplicitAtlas) return [out({ targetAgent: 'SAGE',  intentDetected: 'continue_sage',  pendingHandoff: null })];
if (activeAgent === 'ATLAS' && !isNew && !hasSaludo && !hasExplicitSage)  return [out({ targetAgent: 'ATLAS', intentDetected: 'continue_atlas', pendingHandoff: null })];

// ── REGLA 2: Botones interactivos ────────────────────────────
if (msgType === 'button_reply') {
  if (txt.includes('cotizar') || txt.includes('quote')    || txt.includes('cotar'))    return [out({ targetAgent: 'NOVA', intentDetected: 'cotizar_button',  pendingHandoff: 'SAGE'  })];
  if (txt.includes('comparar') || txt.includes('compare') || txt.includes('comparar')) return [out({ targetAgent: 'NOVA', intentDetected: 'comparar_button', pendingHandoff: 'ATLAS' })];
  if (txt.includes('agendar')  || txt.includes('schedule') || txt.includes('agendar')) return [out({ targetAgent: 'NOVA', intentDetected: 'agendar_button',  pendingHandoff: null   })];
  return [out({ targetAgent: 'NOVA', intentDetected: 'unknown_button', pendingHandoff: null })];
}

// ── REGLA 3: Keywords trilingüe ──────────────────────────────
const KW_COTIZAR = [
  'cotiz','precio','cuánto','cuanto','costo','tarifa',
  'implante','corona dental','carilla','veneer','ortodoncia','bracket','invisalign','alineador','blanqueamiento','endodoncia','conducto','extraccion','extracción','puente dental','limpieza dental','periodoncia','protesis','prótesis',
  'rinoplastia','liposuccion','liposucción','abdominoplastia','mamario','aumento de busto','reduccion mamaria','reducción mamaria','bichectomia','bichectomía','blefaroplastia','bbl','lifting facial','otoplastia',
  'procedimiento','cirugía','cirugia','dental','dentista','diente','muela',
  'carie','caries','dolor de muela','dolor dental','me duele','empaste',
  'relleno','funda','corona','sarro','encia','encías','sangrado',
  'nariz','arrugas','flacidez','papada','rejuven','mejillas',
  'quote','how much','price','rate','fee',
  'tooth','teeth','implant','dental crown','braces','aligner','whitening','root canal','bridge','denture','deep cleaning','wisdom','molar','premolar','incisor','canine',
  'rhinoplasty','liposuction','tummy tuck','breast implant','breast augmentation','breast reduction','blepharoplasty','facelift','face lift','ear surgery',
  'procedure','surgery','treatment','dental work','dental procedure',
  'cotação','preço','quanto custa','quanto é','valor do',
  'implante dental','coroa','faceta','ortodontia','aparelho dentário','clareamento','canal','extração','ponte dentária','prótese dentária','limpeza dental',
  'lipoaspiração','abdominoplastia','mamoplastia','aumento de seios','redução mamária','bichectomia','blefaroplastia','lifting facial',
  'procedimento','cirurgia','dentista','dente','molar','tratamento dental'
];
const KW_COMPARAR = [
  'comparar','comparacion','comparativa','destino','viajar','viaje','vuelo','hotel','turismo médico','turismo medico','costo total','costo del viaje','cuánto me sale','hospedaje',
  'méxico','mexico','colombia','bogotá','bogota','medellín','medellin','cartagena','perú','peru','lima','costa rica','argentina','buenos aires','dominicana','miami','cancún','cancun','ciudad de mexico','santo domingo',
  'compare','comparison','destination','travel','trip','flight','medical tourism','medical travel','total cost','accommodation','lodging','where to go','best destination','cheapest',
  'comparar','comparação','viagem','voo','hospedagem','alojamento','custo total','melhor destino','mais barato'
];
const KW_AGENDAR = [
  'agendar','cita','reservar','agenda','turno','disponibilidad','horario','me atiendan','consulta',
  'appointment','schedule','book ','booking','see a doctor','availability','available','make an appointment','want to see',
  'marcar consulta','marcar uma','reservar consulta','disponibilidade','atendimento','quero consulta'
];

// v2.4: match por INICIO DE PALABRA (\b + prefijo), nunca substring libre.
// 'encia' ya no matchea "presencial"; 'lima' sigue matcheando "Lima".
const kwHit = (list) => list.some(kw => {
  const k = normalize(kw).trim();
  if (!k) return false;
  return new RegExp('\\b' + k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).test(txtN);
});
const hasCotizar  = kwHit(KW_COTIZAR);
const hasComparar = kwHit(KW_COMPARAR);
const hasAgendar  = kwHit(KW_AGENDAR);

if (hasCotizar)  return [out({ targetAgent: 'NOVA', intentDetected: 'cotizar_keyword',  pendingHandoff: 'SAGE'  })];
if (hasComparar) return [out({ targetAgent: 'NOVA', intentDetected: 'comparar_keyword', pendingHandoff: 'ATLAS' })];
if (hasAgendar)  return [out({ targetAgent: 'NOVA', intentDetected: 'agendar_keyword',  pendingHandoff: null   })];
if (hasSaludo)   return [out({ targetAgent: 'NOVA', intentDetected: 'saludo',           pendingHandoff: null   })];

return [out({ targetAgent: 'NOVA', intentDetected: 'unclear', pendingHandoff: null })];

// ============================================================
// PREPARAR CLAUDE NLU v1.0 — Paso 1
// Solo llega aquí cuando keywords no detectaron intención clara.
// Haiku clasifica intención y detecta idioma del mensaje.
// ============================================================
const session = $json;

const systemPrompt = `Eres un clasificador de intenciones para Pangi, plataforma de turismo médico latinoamericana.

INTENCIONES DISPONIBLES:
- cotizar: quiere cotizar, ver precio o info sobre procedimiento médico/dental
- comparar: quiere comparar destinos médicos o calcular costo total del viaje
- agendar: quiere agendar cita, consulta o ver disponibilidad de médico
- saludo: saludo, inicio de conversación, agradecimiento, afirmación genérica
- unclear: no es posible determinar la intención con confianza suficiente

IDIOMA DEL MENSAJE: es (español), en (inglés), pt (portugués)

REGLAS:
1. Si el mensaje menciona un procedimiento médico o dental, es 'cotizar'
2. Si el mensaje menciona destinos, viajes, costos de viaje, es 'comparar'
3. Si el mensaje menciona agendar, cita, turno, appointment, es 'agendar'
4. Si confidence < 0.70, usa 'unclear'
5. Responde SOLO con JSON válido, sin markdown, sin explicación:

{"intent":"cotizar","language":"es","confidence":0.92}`;

return [{ json: {
  _session: session,
  claudePayload: {
    model: "claude-haiku-4-5-20251001",
    max_tokens: 60,
    system: systemPrompt,
    messages: [{ role: "user", content: session.messageText || "" }]
  }
}}];

// ============================================================
// PROCESAR INTENT CLAUDE v1.0 — Paso 1
// Merge del resultado de Claude con el contexto de sesión.
// Fallback robusto: cualquier fallo → mantiene 'unclear',
// NOVA mostrará el menú de opciones al usuario.
// ============================================================
const httpResult = $json;
const prepData   = $('📦 Preparar — Claude NLU').first().json;
const session    = prepData._session;

// Default: mantener resultado del keyword router
let intentDetected   = session.intentDetected;  // 'unclear'
let pendingHandoff   = session.pendingHandoff;  // null
let targetAgent      = session.targetAgent;     // 'NOVA'
let detectedLanguage = session.detectedLanguage;

// Mapeo: intent Claude → estructura del router
const INTENT_MAP = {
  cotizar:  { handoff: 'SAGE',  intent: 'cotizar_claude'  },
  comparar: { handoff: 'ATLAS', intent: 'comparar_claude' },
  agendar:  { handoff: null,    intent: 'agendar_claude'  },
  saludo:   { handoff: null,    intent: 'saludo_claude'   },
  unclear:  { handoff: null,    intent: 'unclear'         }
};

const VALID_INTENTS = Object.keys(INTENT_MAP);

try {
  // httpResult puede ser la respuesta de Claude o un error de continueOnFail
  const content = httpResult?.content?.[0]?.text;
  if (content) {
    const clean  = content.replace(/```json\n?|```\n?/g, '').trim();
    const parsed = JSON.parse(clean);

    if (
      VALID_INTENTS.includes(parsed.intent) &&
      typeof parsed.confidence === 'number' &&
      parsed.confidence >= 0.70
    ) {
      const mapping  = INTENT_MAP[parsed.intent];
      intentDetected = mapping.intent;
      pendingHandoff = mapping.handoff;
      // targetAgent siempre NOVA: la lógica de handoff está en NOVA motor

      // Actualizar idioma solo si Claude lo detectó con certeza
      if (parsed.language && ['es','en','pt'].includes(parsed.language)) {
        detectedLanguage = parsed.language;
      }
    }
    // confidence < 0.70 → mantiene 'unclear' → NOVA da menú orientador
  }
} catch(e) {
  // Claude falló, timeout, JSON inválido, etc.
  // Fallback silencioso: 'unclear' → NOVA orienta al usuario
  // No interrumpir la conversación por un fallo de API
}

return [{ json: {
  ...session,
  intentDetected,
  pendingHandoff,
  targetAgent,
  detectedLanguage,
  _nluSource: intentDetected.includes('_claude') ? 'claude' : 'keywords_fallback'
}}];

const inp  = $input.first().json;
const LANG = inp.detectedLanguage || 'es';
const ctx  = inp.sessionContext || {};
const NOTICE = {
  es: `📋 *Aviso de Privacidad*\n\nAl usar este servicio aceptas que Pangi procese tu información de salud con fines de orientación médica. Tus datos se almacenan de forma segura y no se comparten con terceros sin tu autorización.\n\n_Más información en pangi.com/privacy_\n\n*¿Aceptas continuar?* Responde *sí* para continuar o *no* para cancelar.`,
  en: `📋 *Privacy Notice*\n\nBy using this service you agree that Pangi may process your health information for medical guidance purposes. Your data is securely stored and not shared with third parties without your authorization.\n\n_More info at pangi.com/privacy_\n\n*Do you accept to continue?* Reply *yes* to continue or *no* to cancel.`,
  pt: `📋 *Aviso de Privacidade*\n\nAo usar este serviço você concorda que o Pangi processe suas informações de saúde para fins de orientação médica. Seus dados são armazenados com segurança e não são compartilhados com terceiros sem sua autorização.\n\n_Mais informações em pangi.com/privacy_\n\n*Você aceita continuar?* Responda *sim* para continuar ou *não* para cancelar.`
};
const lang = LANG in NOTICE ? LANG : 'es';

// Detectar si el primer mensaje tiene intención relevante
const pendingTxt  = inp.messageText || '';
const pendingTxtN = pendingTxt.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const isTrivialFirst = /^(hola|hi|hey|hello|ol[aá]|oi|bom dia|buenas?|inicio|start|begin|come[cç]ar|ok|yes|sim|dale)[\s!.]*$/i.test(pendingTxt.trim());
const hasIntentFirst = !isTrivialFirst && /cotiz|implante|rinoplas|liposu|mamario|dental|diente|muela|ortodoncia|blanquea|endodoncia|carilla|veneer|corona|puente|protesis|extrac|procedimiento|cirugia|cirugía|nariz|quote|price|surgery|tooth|teeth|compar|destino|turismo|agendar|cita|reservar|appointment|schedule|cotação|preço|cirurgia/.test(pendingTxtN);

return [{ json: {
  responseText:      NOTICE[lang],
  newActiveAgent:    inp.activeAgent || 'NOVA',
  newSessionState:   'awaiting_consent',
  newSessionContext: {
    ...ctx,
    awaiting_consent: true,
    consent_given:    false,
    language:         lang,
    _pending_intent:  hasIntentFirst ? pendingTxt : null
  },
  userId:    inp.userId,
  sessionId: inp.sessionId,
  userName:  inp.userName || null,
  remoteJid: inp.remoteJid,
  instance:  inp.instance
}}];

const inp  = $input.first().json;
const LANG = inp.detectedLanguage || 'es';
const ctx  = inp.sessionContext || {};

const GOODBYE = {
  es: `Entendemos tu decisión. Sin aceptar el aviso de privacidad no es posible usar los servicios de Pangi.\n\nSi cambias de opinión en el futuro, puedes escribirnos nuevamente. ¡Hasta pronto! 👋`,
  en: `We understand your decision. Without accepting the privacy notice, we cannot provide Pangi's services.\n\nIf you change your mind in the future, feel free to message us again. Goodbye! 👋`,
  pt: `Entendemos sua decisão. Sem aceitar o aviso de privacidade, não é possível usar os serviços do Pangi.\n\nSe mudar de ideia no futuro, pode nos escrever novamente. Até logo! 👋`
};

const lang = LANG in GOODBYE ? LANG : 'es';

return [{ json: {
  responseText:      GOODBYE[lang],
  newActiveAgent:    'NOVA',
  newSessionState:   'consent_refused',
  newSessionContext: {
    ...ctx,
    awaiting_consent: false,
    consent_given:    false
  },
  userId:    inp.userId,
  sessionId: inp.sessionId,
  userName:  inp.userName || null,
  remoteJid: inp.remoteJid,
  instance:  inp.instance
}}];

const inp  = $input.first().json;
const LANG = inp.detectedLanguage || 'es';
const ctx  = inp.sessionContext || {};
const fn   = inp.userName ? inp.userName.split(' ')[0] : null;
const nm   = fn ? ` ${fn}` : '';

const WELCOME = {
  es: `✅ *Gracias por aceptar${nm}.*\n\n👋 Soy *NOVA*, tu asistente de salud en Pangi.\n\n¿En qué puedo ayudarte hoy?\n\n💰 Escribe *cotizar* — Recibe precios precisos de médicos\n🗺️ Escribe *comparar* — Analiza el costo total de tu viaje médico\n🗓️ Escribe *agendar* — Busca médicos y reserva citas`,
  en: `✅ *Thank you for accepting${nm}.*\n\n👋 I'm *NOVA*, your Pangi health assistant.\n\nHow can I help you today?\n\n💰 Type *quote* — Get precise pricing from doctors\n🗺️ Type *compare* — Analyze your full medical trip cost\n🗓️ Type *schedule* — Find doctors and book appointments`,
  pt: `✅ *Obrigado por aceitar${nm}.*\n\n👋 Sou *NOVA*, sua assistente de saúde do Pangi.\n\nComo posso te ajudar hoje?\n\n💰 Escreva *cotizar* — Receba preços precisos de médicos\n🗺️ Escreva *comparar* — Analise o custo total da sua viagem médica\n🗓️ Escreva *agendar* — Encontre médicos e reserve consultas`
};

const lang = LANG in WELCOME ? LANG : 'es';

// Si el primer mensaje tenía una intención clara, rutear directo sin pasar por NOVA
const pendingText  = ctx._pending_intent || '';
const pendingTextN = pendingText.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const hasCotizar   = !!pendingText && /cotiz|implante|rinoplas|liposu|mamario|dental|diente|muela|ortodoncia|blanquea|endodoncia|carilla|veneer|corona|puente|protesis|extrac|procedimiento|cirugia|cirugía|quote|price|surgery|tooth|teeth|cotação|preço|cirurgia/.test(pendingTextN);
const hasComparar  = !!pendingText && !hasCotizar && /compar|destino|turismo|costo.total|compare|destination|comparar/.test(pendingTextN);
const hasAgendar   = !!pendingText && !hasCotizar && !hasComparar && /agendar|cita|reservar|appointment|schedule|consulta/.test(pendingTextN);

const detectedPending = hasCotizar ? 'SAGE' : hasComparar ? 'ATLAS' : hasAgendar ? 'NOVA_AGENDAR' : null;
if (detectedPending) {
  const targetAgent = hasCotizar ? 'SAGE' : hasComparar ? 'ATLAS' : 'NOVA';
  const pendingHandoff = hasCotizar ? 'SAGE' : hasComparar ? 'ATLAS' : null;
  const welcomePrefix = lang === 'en'
    ? `✅ *Thank you for accepting${nm}.*\n\n`
    : lang === 'pt'
    ? `✅ *Obrigado por aceitar${nm}.*\n\n`
    : `✅ *Gracias por aceptar${nm}.*\n\n`;

  return [{ json: {
    responseText:      welcomePrefix + WELCOME[lang],
    newActiveAgent:    'NOVA',
    newSessionState:   'initial_presented',
    newSessionContext: {
      ...ctx,
      consent_given:    true,
      awaiting_consent: false,
      language:         lang,
      nova:             { state: 'initial_presented' },
      pendingHandoff:   detectedPending,
      pendingMessage:   pendingText,
      _pending_intent:  null
    },
    intentDetected:    hasCotizar ? 'cotizar_keyword' : hasComparar ? 'comparar_keyword' : 'agendar_keyword',
    userId:    inp.userId,
    sessionId: inp.sessionId,
    userName:  inp.userName || null,
    remoteJid: inp.remoteJid,
    instance:  inp.instance
  }}];
}

return [{ json: {
  responseText:      WELCOME[lang],
  newActiveAgent:    'NOVA',
  newSessionState:   'initial_presented',
  newSessionContext: {
    ...ctx,
    consent_given:    true,
    awaiting_consent: false,
    language:         lang,
    nova: { state: 'initial_presented' }
  },
  userId:    inp.userId,
  sessionId: inp.sessionId,
  userName:  inp.userName || null,
  remoteJid: inp.remoteJid,
  instance:  inp.instance
}}];

// Recuperar contexto del nodo de preparación (anterior al HTTP)
const prep = $('📤 Preparar Envío Telegram').first().json;

return [{ json: {
  operation: 'updateSession',
  params: {
    sessionId: prep._sessionId,
    agent:     prep._newActiveAgent,
    state:     prep._newSessionState,
    context:   prep._newSessionContext
  },
  // Transportar para guardar mensaje saliente
  _prep: prep
}}];

const prep = $('📦 Payload — Update Session').first().json._prep;

return [{ json: {
  operation: 'saveMessage',
  params: {
    userId:      prep._userId,
    sessionId:   prep._sessionId,
    agent:       prep._newActiveAgent,
    role:        'assistant',
    message:     prep._responseText,
    messageType: 'text'
  }
}}];

// v2.0 — Canal-agnóstico: phone viene del sobre canónico ('tg:<chat_id>' en Telegram).
// El idioma default aprovecha language_code de Telegram si es es/en/pt.
const msg = $('🔎 Extraer y Validar Mensaje').first().json;
return [{ json: {
  operation: 'getOrCreateUser',
  params: {
    phone:    msg.phone,
    name:     msg.pushName || null,
    language: msg.tgLanguage || 'es'
  }
}}];
